    image: "/pharmacy/106/practical/q211.png",

    question:
      "処方２で用いられた薬物は、プロテアーゼであるジペプチジルペプチダーゼ-4（DPP-4）の基質結合部位に結合して阻害することにより血糖降下作用を示す。この薬物は、以下の図に示したような DPP-4 の基質結合部位のアルギニン残基、グルタミン酸残基、フェニルアラニン残基の側鎖とそれぞれ相互作用する官能基をもつ。処方２の薬物の構造はどれか。１つ選べ。ただし、グアニジノ基は水素結合相互作用におけるプロトン供与体として働く。",

