      "FDG-PET/CTでは、¹⁸F-FDGがブドウ糖と同じように細胞へ取り込まれる性質を利用します。食後で血糖値が高いとFDGの取り込みに影響し、画像評価がしにくくなるため、検査前は一定時間の絶食が必要です。したがって「検査4時間前から食事をとらない」は適切です。メトホルミンは、ヨード造影剤を用いるCTで腎機能などに注意して休薬を検討することはありますが、FDG-PET/CTだから一律に検査2日前や検査後2日間中止するとはいえません。ワルファリンも通常、PET/CT検査のみを理由に中止しません。5％ブドウ糖液の投与はFDGと競合し、検査に影響するため不適切です。"
