    question:
      "57歳男性。5年前より、2型糖尿病及び心房細動に対して以下の薬剤が処方されている。今回、悪性リンパ腫が疑われたため、確定診断のために¹⁸F-フルデオキシグルコース（FDG）を用いたポジトロン断層・コンピューター断層複合撮影（PET/CT）検査を行うこととなった。\n\n（処方）\nメトホルミン塩酸塩錠250 mg 1回1錠（1日2錠）\n1日2回 朝夕食後 30日分\nワルファリンカリウム錠1 mg 1回2錠（1日2錠）\n1日1回 夕食後 30日分\n\nこの患者に投与される¹⁸F-FDG及びPET/CT検査に関する記述のうち、誤っているのはどれか。1つ選べ。",

