    question:
      "59歳男性。体重72 kg。糖尿病、高血圧、脂質異常症に対する治療を受けていた。同時期にうつ病に対しパロキセチンで治療を開始したが、抑うつが改善した後気分が高揚したため、双極性障害と診断され任意入院した。入院後特に焦燥感が強いと患者から訴えがあった。現在の服用薬剤は処方1のとおり。\n\n（処方1）\n炭酸リチウム錠200 mg 1回2錠（1日2錠）\n1日1回 朝食後 14日分\n\nリスペリドン錠1 mg 1回3錠（1日6錠）\n1日2回 朝夕食後 14日分\n\nロスバスタチン錠2.5 mg 1回1錠（1日1錠）\n1日1回 夕食後 14日分\n\nメトホルミン塩酸塩錠500 mg 1回1錠（1日2錠）\n1日2回 朝夕食後 14日分\n\nオルメサルタン メドキソミル錠20 mg 1回1錠（1日1錠）\n1日1回 朝食後 14日分\n\n処方1のいずれかの薬物の薬理作用にあてはまるのはどれか。2つ選べ。",

