      "家族から、最近、処方薬が変更になったとの情報を得た。そのため、変更された薬物により意識消失が引き起こされた可能性があると考えた。現在、患者は以下の薬剤を服用している。最も疑わしいのはどれか。1つ選べ。\n\nシベンゾリンコハク酸塩錠 100 mg　1回1錠（1日3錠）\n　　　　　　　　　　　　　　　　1日3回　朝昼夕食後\nカルベジロール錠 10 mg　　　　　1回1錠（1日1錠）\nワルファリンカリウム錠 5 mg　　 1回1錠（1日1錠）\nフロセミド錠 40 mg　　　　　　　1回1錠（1日1錠）\nランソプラゾール腸溶性口腔内崩壊錠 15 mg　1回1錠（1日1錠）\n　　　　　　　　　　　　　　　　1日1回　朝食後",

