      "17歳男性。2日前、体育の授業でバスケットボールをした際、左臀部の痛みを自覚した後に腫れも出現した。左臀部は硬く腫脹し、筋肉内出血が疑われた。受診時の血液検査結果は以下のとおりであった。赤血球数 375×10^4/μL、Hb 11.2 g/dL、Ht 35%、白血球数 6,800/μL、血小板数 38×10^4/μL、プロトロンビン時間 11.0秒（基準値 10〜14）、活性化部分トロンボプラスチン時間 72.0秒（基準対照 32.2）、出血時間 3分30秒（基準値 1.0〜5.0分）、AST 62 IU/L、ALT 21 IU/L、LDH 350 IU/L、血清クレアチニン値 0.6 mg/dL、ADAMTS13抗体陰性、フィブリノゲン・フィブリン分解産物 3 μg/mL（基準値＜5）。本例にデスモプレシン注射液の投与を行ったところ、出血症状の改善が認められた。",
